('topic-edx-ial-pure1-01', 'subj-edx-ial-pure1', 'Algebra and functions', 'Indices, surds, quadratic equations, completing the square, discriminant, simultaneous equations, inequalities, and cubic polynomial sketches.', 1, 8, 'medium', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
