('topic-edx-ial-pure2-01', 'subj-edx-ial-pure2', 'Proof and algebra', 'Proof by deduction, exhaustion and counter-example; remainder and factor theorems; algebraic division.', 1, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-ial-pure2-02', 'subj-edx-ial-pure2', 'Coordinate geometry of circles', 'Equation of circle (x-a)^2 + (y-b)^2 = r^2, tangent and normal properties, and intersection of lines and circles.', 2, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-ial-pure2-03', 'subj-edx-ial-pure2', 'Sequences and series', 'Arithmetic and geometric progressions, general terms, sum of n terms, sum to infinity, and binomial expansion (a + bx)^n.', 3, 7, 'medium', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
