('topic-edx-ial-pure2-05', 'subj-edx-ial-pure2', 'Exponentials and logarithms', 'Exponential functions, natural logarithm, laws of logarithms, solving equations, and modeling non-linear data using log transformations.', 5, 6, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-ial-pure2-06', 'subj-edx-ial-pure2', 'Differentiation and integration', 'Differentiation of e^x and ln x, integration of standard exponential/trigonometric forms, and the trapezium rule.', 6, 6, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
